(59,[[149,171],[220,242],[250,290],[302,324],[391,413],[480,502],[548,563]],'AI Normalize power1.2 at≥7; ParentalBond total power1.25≥7 else1.5; terrain1.3≥8 else1.5 only medium skill; high-skill/internal/player target badge Defense/SpDef×1.1. Critical multiplier flag1.5vs2. Medium-skill Minimize perfect accuracy≥6, Toxic poison-user flag sets estimated baseaccuracy0. Secondary-effect bonus5 excludes old environment effect unless≥6.','WP51/WP52A rough damage/accuracy'),
